INSERT INTO session.drills (id, name, description, library_type, owner_coach_id, status, metadata, trans_key, version, source_drill_id) VALUES ('00000000-0000-4000-8000-000000000001', 'Toe Taps', 'Rapid alternating toe taps on top of the ball to develop quick feet and ball feel.', 'PLATFORM', NULL, 'ACTIVE', '{"intensity": 2, "repDensity": 40, "matchRealism": 1, "weakFootBias": true, "cognitiveLoad": 1, "pressureLevel": 1, "primarySkills": ["ball_mastery"], "coachingPoints": ["Keep the ball close under your feet", "Use the front pad of each toe", "Increase speed gradually", "Stay light on your feet"], "difficultyTier": "U8", "skillWeighting": {"balance": 10, "ball_mastery": 70, "coordination": 20}, "secondarySkills": ["coordination", "balance"], "equipmentRequired": ["ball"], "recommendedGroupSize": "1–4"}', 'sessDrill.toeTaps', 0, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO session.drills (id, name, description, library_type, owner_coach_id, status, metadata, trans_key, version, source_drill_id) VALUES ('00000000-0000-4000-8000-000000000002', 'Inside-Outside Roll', 'Roll the ball across the body using inside-outside foot alternations to build touch and control.', 'PLATFORM', NULL, 'ACTIVE', '{"intensity": 2, "repDensity": 20, "matchRealism": 2, "weakFootBias": true, "cognitiveLoad": 2, "pressureLevel": 1, "primarySkills": ["ball_mastery", "close_control"], "coachingPoints": ["Soft touch on every contact", "Eyes up between touches", "Stay balanced over the ball", "Progress to both feet equally"], "difficultyTier": "U10", "skillWeighting": {"footwork": 10, "ball_mastery": 60, "close_control": 30}, "secondarySkills": ["footwork"], "equipmentRequired": ["ball"], "recommendedGroupSize": "1–6"}', 'sessDrill.insideOutsideRoll', 0, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO session.drills (id, name, description, library_type, owner_coach_id, status, metadata, trans_key, version, source_drill_id) VALUES ('00000000-0000-4000-8000-000000000003', 'L-Shape Mastery', 'Player uses sole to pull back, then inside foot to drag the ball in an L-pattern.', 'PLATFORM', NULL, 'ACTIVE', '{"intensity": 2, "repDensity": 16, "matchRealism": 2, "weakFootBias": false, "cognitiveLoad": 2, "pressureLevel": 1, "primarySkills": ["ball_mastery", "close_control"], "coachingPoints": ["Plant foot points in direction of travel", "Sole pull stays behind the body line", "Drive away with purpose after the shape", "Build speed only after technique is clean"], "difficultyTier": "U10", "skillWeighting": {"ball_mastery": 55, "close_control": 30, "change_of_direction": 15}, "secondarySkills": ["change_of_direction"], "equipmentRequired": ["ball", "cones"], "recommendedGroupSize": "1–4"}', 'sessDrill.lShapeMastery', 0, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO session.drills (id, name, description, library_type, owner_coach_id, status, metadata, trans_key, version, source_drill_id) VALUES ('00000000-0000-4000-8000-000000000004', 'Foundation Juggling Sequence', 'Structured juggling progression: thigh-to-thigh, foot-to-thigh, continuous foot juggle.', 'PLATFORM', NULL, 'ACTIVE', '{"intensity": 1, "repDensity": 30, "matchRealism": 1, "weakFootBias": true, "cognitiveLoad": 2, "pressureLevel": 1, "primarySkills": ["ball_mastery", "first_touch"], "coachingPoints": ["Cushion the ball on contact — don''t stab", "Minimal knee bend to control height", "Use laces not toes for clean strikes", "Track the ball all the way to contact"], "difficultyTier": "U12", "skillWeighting": {"first_touch": 35, "ball_mastery": 50, "coordination": 15}, "secondarySkills": ["coordination", "aerial_control"], "equipmentRequired": ["ball"], "recommendedGroupSize": "1–8"}', 'sessDrill.foundationJugglingSequence', 0, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO session.drills (id, name, description, library_type, owner_coach_id, status, metadata, trans_key, version, source_drill_id) VALUES ('00000000-0000-4000-8000-000000000005', 'Cone Slalom Ball Mastery', 'Player dribbles a cone slalom using only inside and outside touches.', 'PLATFORM', NULL, 'ACTIVE', '{"intensity": 3, "repDensity": 10, "matchRealism": 3, "weakFootBias": false, "cognitiveLoad": 2, "pressureLevel": 2, "primarySkills": ["close_control", "dribbling"], "coachingPoints": ["Keep the ball within 1 foot of your body", "Lean into each gate", "Use alternate feet at each cone", "Accelerate between gates"], "difficultyTier": "U12", "skillWeighting": {"dribbling": 35, "ball_mastery": 15, "close_control": 50}, "secondarySkills": ["ball_mastery", "agility"], "equipmentRequired": ["ball", "cones"], "recommendedGroupSize": "2–8"}', 'sessDrill.coneSlalomBallMastery', 0, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO session.drills (id, name, description, library_type, owner_coach_id, status, metadata, trans_key, version, source_drill_id) VALUES ('00000000-0000-4000-8000-000000000006', 'Static Finish — Inside Foot', 'Stationary shooting practice using the inside foot for placement and accuracy.', 'PLATFORM', NULL, 'ACTIVE', '{"intensity": 2, "repDensity": 20, "matchRealism": 2, "weakFootBias": true, "cognitiveLoad": 1, "pressureLevel": 1, "primarySkills": ["finishing", "shooting_technique"], "coachingPoints": ["Lock the ankle on contact", "Strike through the middle of the ball", "Non-kicking foot beside the ball", "Follow through toward target"], "difficultyTier": "U8", "skillWeighting": {"accuracy": 10, "finishing": 60, "shooting_technique": 30}, "secondarySkills": ["accuracy"], "equipmentRequired": ["ball", "goal"], "recommendedGroupSize": "2–6"}', 'sessDrill.staticFinishInsideFoot', 0, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO session.drills (id, name, description, library_type, owner_coach_id, status, metadata, trans_key, version, source_drill_id) VALUES ('00000000-0000-4000-8000-000000000007', 'Turn and Shoot', 'Receive a pass with back to goal, turn, and shoot first time.', 'PLATFORM', NULL, 'ACTIVE', '{"intensity": 3, "repDensity": 12, "matchRealism": 4, "weakFootBias": false, "cognitiveLoad": 3, "pressureLevel": 2, "primarySkills": ["finishing", "first_touch"], "coachingPoints": ["Check shoulder before the ball arrives", "Decide turn direction before receiving", "Positive first touch away from goal", "Strike early — don''t over-touch"], "difficultyTier": "U14", "skillWeighting": {"turning": 20, "finishing": 45, "first_touch": 35}, "secondarySkills": ["turning", "decision_making"], "equipmentRequired": ["ball", "goal", "cones"], "recommendedGroupSize": "3–8"}', 'sessDrill.turnAndShoot', 0, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO session.drills (id, name, description, library_type, owner_coach_id, status, metadata, trans_key, version, source_drill_id) VALUES ('00000000-0000-4000-8000-000000000008', 'Shooting on the Move', 'Player receives a lateral pass while moving and finishes on goal without breaking stride.', 'PLATFORM', NULL, 'ACTIVE', '{"intensity": 3, "repDensity": 14, "matchRealism": 4, "weakFootBias": true, "cognitiveLoad": 2, "pressureLevel": 2, "primarySkills": ["shooting_technique", "finishing"], "coachingPoints": ["Keep head steady through contact", "Plant foot pointed at the target", "Strike before pace is lost", "Aim for corners — power without control is wasted"], "difficultyTier": "U14", "skillWeighting": {"movement": 15, "finishing": 35, "shooting_technique": 50}, "secondarySkills": ["movement", "coordination"], "equipmentRequired": ["ball", "goal", "cones"], "recommendedGroupSize": "2–6"}', 'sessDrill.shootingOnTheMove', 0, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO session.drills (id, name, description, library_type, owner_coach_id, status, metadata, trans_key, version, source_drill_id) VALUES ('00000000-0000-4000-8000-000000000009', '1v1 Finishing Under Pressure', 'Attacker receives, beats a passive defender, and shoots within a 5-second window.', 'PLATFORM', NULL, 'ACTIVE', '{"intensity": 4, "repDensity": 10, "matchRealism": 5, "weakFootBias": false, "cognitiveLoad": 4, "pressureLevel": 4, "primarySkills": ["finishing", "dribbling_under_pressure"], "coachingPoints": ["Commit the defender before the move", "Create the angle — don''t shoot from straight on", "Stay calm — your foot technique does not change under pressure", "Score with purpose not panic"], "difficultyTier": "U16", "skillWeighting": {"finishing": 40, "decision_making": 25, "dribbling_under_pressure": 35}, "secondarySkills": ["decision_making", "composure"], "equipmentRequired": ["ball", "goal", "cones"], "recommendedGroupSize": "4–10"}', 'sessDrill.oneVOneFinishingUnderPressure', 0, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO session.drills (id, name, description, library_type, owner_coach_id, status, metadata, trans_key, version, source_drill_id) VALUES ('00000000-0000-4000-8000-000000000010', 'Volley Finishing', 'Players practice volleys from crossed balls or throws, focusing on technique and timing.', 'PLATFORM', NULL, 'ACTIVE', '{"intensity": 3, "repDensity": 10, "matchRealism": 4, "weakFootBias": true, "cognitiveLoad": 3, "pressureLevel": 2, "primarySkills": ["shooting_technique", "aerial_control"], "coachingPoints": ["Watch the ball all the way to contact", "Get side-on — do not face the ball square", "Keep toes down and lock ankle", "Aim across goal for placement"], "difficultyTier": "U16", "skillWeighting": {"timing": 20, "aerial_control": 30, "shooting_technique": 50}, "secondarySkills": ["finishing", "timing"], "equipmentRequired": ["ball", "goal"], "recommendedGroupSize": "3–8"}', 'sessDrill.volleyFinishing', 0, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO session.drills (id, name, description, library_type, owner_coach_id, status, metadata, trans_key, version, source_drill_id) VALUES ('00000000-0000-4000-8000-000000000011', 'Cruyff Turn', 'Classic feint: fake to pass or cross, pull ball behind standing leg with inside foot.', 'PLATFORM', NULL, 'ACTIVE', '{"intensity": 2, "repDensity": 14, "matchRealism": 3, "weakFootBias": false, "cognitiveLoad": 2, "pressureLevel": 2, "primarySkills": ["dribbling", "turning"], "coachingPoints": ["Sell the fake with your body lean", "Drag behind the standing leg — not across", "Explode out in new direction immediately", "Head up after turn to make next decision"], "difficultyTier": "U12", "skillWeighting": {"turning": 35, "deception": 15, "dribbling": 50}, "secondarySkills": ["deception", "close_control"], "equipmentRequired": ["ball", "cones"], "recommendedGroupSize": "2–8"}', 'sessDrill.cruyffTurn', 0, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO session.drills (id, name, description, library_type, owner_coach_id, status, metadata, trans_key, version, source_drill_id) VALUES ('00000000-0000-4000-8000-000000000012', 'Step-Over to Accelerate', 'Use step-over(s) to unbalance a defender, then burst into space with outside foot.', 'PLATFORM', NULL, 'ACTIVE', '{"intensity": 3, "repDensity": 16, "matchRealism": 4, "weakFootBias": true, "cognitiveLoad": 2, "pressureLevel": 2, "primarySkills": ["dribbling", "skill_moves"], "coachingPoints": ["Circle the ball — don''t kick it", "Plant foot stays behind ball line", "Drive outside foot away immediately", "Lean opposite direction to the step-over"], "difficultyTier": "U14", "skillWeighting": {"dribbling": 55, "skill_moves": 30, "acceleration": 15}, "secondarySkills": ["agility", "acceleration"], "equipmentRequired": ["ball", "cones"], "recommendedGroupSize": "2–8"}', 'sessDrill.stepOverToAccelerate', 0, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO session.drills (id, name, description, library_type, owner_coach_id, status, metadata, trans_key, version, source_drill_id) VALUES ('00000000-0000-4000-8000-000000000013', 'Elastico / Flip-Flap', 'Touch ball outside then whip inside with same foot in one fast motion to beat the defender.', 'PLATFORM', NULL, 'ACTIVE', '{"intensity": 3, "repDensity": 12, "matchRealism": 3, "weakFootBias": false, "cognitiveLoad": 3, "pressureLevel": 2, "primarySkills": ["skill_moves", "close_control"], "coachingPoints": ["The outside touch is the fake", "Whip inside must be sharp and low", "Keep ball very close — inches not feet", "Practise slowly first before adding speed"], "difficultyTier": "U16", "skillWeighting": {"deception": 15, "skill_moves": 60, "close_control": 25}, "secondarySkills": ["dribbling", "deception"], "equipmentRequired": ["ball", "cones"], "recommendedGroupSize": "1–6"}', 'sessDrill.elasticoFlipFlap', 0, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO session.drills (id, name, description, library_type, owner_coach_id, status, metadata, trans_key, version, source_drill_id) VALUES ('00000000-0000-4000-8000-000000000014', 'Pressure Escape Rondo (3v1)', 'Three passers keep the ball in a small square from one defender; after 5 passes, player must dribble out.', 'PLATFORM', NULL, 'ACTIVE', '{"intensity": 4, "repDensity": 8, "matchRealism": 5, "weakFootBias": false, "cognitiveLoad": 5, "pressureLevel": 5, "primarySkills": ["dribbling_under_pressure", "close_control"], "coachingPoints": ["Protect the ball with your body", "Take the ball away from pressure — not into it", "Head up: see all three passers", "Disguise your exit before you take it"], "difficultyTier": "U16", "skillWeighting": {"close_control": 30, "decision_making": 30, "dribbling_under_pressure": 40}, "secondarySkills": ["decision_making", "awareness", "passing"], "equipmentRequired": ["ball", "cones"], "recommendedGroupSize": "4"}', 'sessDrill.pressureEscapeRondo3v1', 0, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO session.drills (id, name, description, library_type, owner_coach_id, status, metadata, trans_key, version, source_drill_id) VALUES ('00000000-0000-4000-8000-000000000015', 'Body Feint and Drive', 'Drop shoulder to fake one direction, drive past passive defender with outside foot on opposite side.', 'PLATFORM', NULL, 'ACTIVE', '{"intensity": 3, "repDensity": 14, "matchRealism": 4, "weakFootBias": true, "cognitiveLoad": 3, "pressureLevel": 3, "primarySkills": ["dribbling", "deception"], "coachingPoints": ["Drop shoulder convincingly — commit to the fake", "Drive must be explosive — not cautious", "Keep ball close to the outside foot", "Look up for the next action immediately"], "difficultyTier": "U14", "skillWeighting": {"deception": 35, "dribbling": 55, "close_control": 10}, "secondarySkills": ["close_control", "agility"], "equipmentRequired": ["ball", "cones"], "recommendedGroupSize": "2–8"}', 'sessDrill.bodyFeintAndDrive', 0, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO session.drills (id, name, description, library_type, owner_coach_id, status, metadata, trans_key, version, source_drill_id) VALUES ('00000000-0000-4000-8000-000000000016', 'Pass and Move (2-Touch)', 'Simple pass and move in pairs — receive, control, pass, move to new position.', 'PLATFORM', NULL, 'ACTIVE', '{"intensity": 2, "repDensity": 30, "matchRealism": 3, "weakFootBias": true, "cognitiveLoad": 2, "pressureLevel": 1, "primarySkills": ["passing", "first_touch"], "coachingPoints": ["Open body before the ball arrives", "Pass into the path of your partner''s run", "Move immediately after the pass", "Weight of pass must match distance"], "difficultyTier": "U8", "skillWeighting": {"passing": 50, "movement": 15, "first_touch": 35}, "secondarySkills": ["movement", "positioning"], "equipmentRequired": ["ball", "cones"], "recommendedGroupSize": "4–12"}', 'sessDrill.passAndMove2Touch', 0, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO session.drills (id, name, description, library_type, owner_coach_id, status, metadata, trans_key, version, source_drill_id) VALUES ('00000000-0000-4000-8000-000000000017', 'Wall Pass (1-2 Combination)', 'Player plays pass to wall player, receives return ball in stride, and continues forward.', 'PLATFORM', NULL, 'ACTIVE', '{"intensity": 3, "repDensity": 20, "matchRealism": 5, "weakFootBias": false, "cognitiveLoad": 3, "pressureLevel": 2, "primarySkills": ["passing", "combination_play"], "coachingPoints": ["Angle body before playing the wall pass", "Drive into space immediately after your pass", "Wall player returns with one touch if possible", "Receiver controls ball into stride — not dead"], "difficultyTier": "U12", "skillWeighting": {"passing": 45, "movement": 15, "combination_play": 40}, "secondarySkills": ["movement", "timing"], "equipmentRequired": ["ball", "cones"], "recommendedGroupSize": "3–8"}', 'sessDrill.wallPassOneTwoCombination', 0, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO session.drills (id, name, description, library_type, owner_coach_id, status, metadata, trans_key, version, source_drill_id) VALUES ('00000000-0000-4000-8000-000000000018', 'Switch of Play from Central', 'Central player receives, spins, and switches play across to opposite wide player under time pressure.', 'PLATFORM', NULL, 'ACTIVE', '{"intensity": 3, "repDensity": 12, "matchRealism": 5, "weakFootBias": false, "cognitiveLoad": 4, "pressureLevel": 3, "primarySkills": ["passing", "switching_play"], "coachingPoints": ["Scan before receiving", "First touch orients toward target", "Long switch must be weighted correctly", "Receiver checks run to meet the ball"], "difficultyTier": "U14", "skillWeighting": {"passing": 50, "awareness": 20, "switching_play": 30}, "secondarySkills": ["first_touch", "awareness", "decision_making"], "equipmentRequired": ["ball", "cones", "bibs"], "recommendedGroupSize": "5–10"}', 'sessDrill.switchOfPlayFromCentral', 0, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO session.drills (id, name, description, library_type, owner_coach_id, status, metadata, trans_key, version, source_drill_id) VALUES ('00000000-0000-4000-8000-000000000019', 'Third-Man Run Combination', 'Two players combine to play in a third runner arriving late into the final third.', 'PLATFORM', NULL, 'ACTIVE', '{"intensity": 4, "repDensity": 8, "matchRealism": 5, "weakFootBias": false, "cognitiveLoad": 5, "pressureLevel": 3, "primarySkills": ["combination_play", "passing"], "coachingPoints": ["Third runner must time the run — not sprint early", "Hold ball long enough to draw the press", "Pass must go in behind the line", "Third man should be onside at the moment of the pass"], "difficultyTier": "U16", "skillWeighting": {"passing": 30, "movement": 20, "combination_play": 50}, "secondarySkills": ["movement", "timing", "awareness"], "equipmentRequired": ["ball", "cones", "bibs", "goal"], "recommendedGroupSize": "6–12"}', 'sessDrill.thirdManRunCombination', 0, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO session.drills (id, name, description, library_type, owner_coach_id, status, metadata, trans_key, version, source_drill_id) VALUES ('00000000-0000-4000-8000-000000000020', 'Receiving in the Half-Turn', 'Player checks to the ball, receives between the lines in a half-turned body position to keep play moving forward.', 'PLATFORM', NULL, 'ACTIVE', '{"intensity": 3, "repDensity": 16, "matchRealism": 5, "weakFootBias": true, "cognitiveLoad": 4, "pressureLevel": 4, "primarySkills": ["first_touch", "receiving_under_pressure"], "coachingPoints": ["Open body sideways before ball arrives", "Check shoulder for pressure before receiving", "First touch goes forward or away from pressure", "Head up instantly to play the next pass"], "difficultyTier": "U16", "skillWeighting": {"awareness": 20, "first_touch": 45, "receiving_under_pressure": 35}, "secondarySkills": ["awareness", "positioning", "passing"], "equipmentRequired": ["ball", "cones", "bibs"], "recommendedGroupSize": "4–8"}', 'sessDrill.receivingInTheHalfTurn', 0, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO development.skill_definitions (code, display_name, display_order, active, rubric_criteria) VALUES ('PAC', 'Pace', 1, true, 'Measures maximum sprint speed over 30m and acceleration in the first 10m.') ON CONFLICT (code) DO NOTHING;
INSERT INTO development.skill_definitions (code, display_name, display_order, active, rubric_criteria) VALUES ('SHO', 'Shooting', 2, true, 'Accuracy, power, and composure when shooting on goal from various distances and angles.') ON CONFLICT (code) DO NOTHING;
INSERT INTO development.skill_definitions (code, display_name, display_order, active, rubric_criteria) VALUES ('PAS', 'Passing', 3, true, 'Range, weight, and accuracy of short, medium, and long-range passes under pressure.') ON CONFLICT (code) DO NOTHING;
INSERT INTO development.skill_definitions (code, display_name, display_order, active, rubric_criteria) VALUES ('DRI', 'Dribbling', 4, true, 'Ability to beat an opponent 1v1 using close control, feints, and changes of direction.') ON CONFLICT (code) DO NOTHING;
INSERT INTO development.skill_definitions (code, display_name, display_order, active, rubric_criteria) VALUES ('PHY', 'Physicality', 5, true, 'Strength, balance, and ability to hold off challenges and win physical duels.') ON CONFLICT (code) DO NOTHING;
INSERT INTO development.skill_definitions (code, display_name, display_order, active, rubric_criteria) VALUES ('DEF', 'Defending', 6, true, 'Positioning, timing of tackles, and ability to win the ball cleanly in defensive duels.') ON CONFLICT (code) DO NOTHING;
INSERT INTO development.skill_definitions (code, display_name, display_order, active, rubric_criteria) VALUES ('WEF', 'Weak Foot', 7, true, 'Quality of striking and control using the non-dominant foot in match situations.') ON CONFLICT (code) DO NOTHING;
INSERT INTO development.skill_definitions (code, display_name, display_order, active, rubric_criteria) VALUES ('F1T', 'First Touch', 8, true, 'Control and ability to set up a second touch instantly from various delivery types.') ON CONFLICT (code) DO NOTHING;
INSERT INTO development.skill_definitions (code, display_name, display_order, active, rubric_criteria) VALUES ('FIN', 'Finishing', 9, true, 'Composure and technique in front of goal in 1v1 and tight-angle situations.') ON CONFLICT (code) DO NOTHING;
INSERT INTO development.skill_definitions (code, display_name, display_order, active, rubric_criteria) VALUES ('1V1', 'One vs One', 10, true, 'Ability to beat a goalkeeper or defender in isolated 1v1 attacking situations.') ON CONFLICT (code) DO NOTHING;
INSERT INTO development.skill_definitions (code, display_name, display_order, active, rubric_criteria) VALUES ('HED', 'Heading', 11, true, 'Accuracy and timing of headed attempts at goal or for clearances.') ON CONFLICT (code) DO NOTHING;
INSERT INTO development.skill_definitions (code, display_name, display_order, active, rubric_criteria) VALUES ('CRO', 'Crossing', 12, true, 'Delivery quality and decision-making when crossing from wide positions.') ON CONFLICT (code) DO NOTHING;
INSERT INTO development.skill_definitions (code, display_name, display_order, active, rubric_criteria) VALUES ('IBS', 'In Behind Runs', 13, true, 'Timing and angle of runs in behind a defensive line to receive through-balls.') ON CONFLICT (code) DO NOTHING;
INSERT INTO development.skill_definitions (code, display_name, display_order, active, rubric_criteria) VALUES ('OBS', 'Off-Ball Scanning', 14, true, 'Awareness and head-movement to gather visual information before receiving the ball.') ON CONFLICT (code) DO NOTHING;
INSERT INTO development.skill_definitions (code, display_name, display_order, active, rubric_criteria) VALUES ('FKI', 'Free Kick Inst.', 15, true, 'Technique, accuracy, and power on set-piece deliveries from dead-ball situations.') ON CONFLICT (code) DO NOTHING;
